// Bundle engine ES modules into classic scripts for the extension.
// MV3 content scripts are classic scripts, and the engine is ESM, so each
// module is wrapped in its own function scope (top-level names never clash)
// and imports become destructuring of the imported module's export object.
// Only the import/export forms the engine uses are supported:
//   import { a, b as c } from './x.js';
//   export function|async function|const|let|class name
// Anything else throws, so a new form can't silently produce a broken bundle.
//
// CLI (run by `npm test` / `npm run e2e` via their pre-scripts): writes
// every entry in TARGETS. No dependencies, no network.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve, relative, basename } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('../../', import.meta.url));

export const TARGETS = [
  { entry: 'engine/src/content.js', out: 'Extension/Resources/content/engine.js' },
  { entry: 'engine/src/background.js', out: 'Extension/Resources/background.js' },
  { entry: 'engine/src/popup.js', out: 'Extension/Resources/popup/popup.js' },
  { entry: 'engine/src/options.js', out: 'Extension/Resources/options/options.js' },
];

const IMPORT_RE = /^import\s*\{([^}]*)\}\s*from\s*'(\.[^']+)';?[ \t]*$/gm;
const EXPORT_DECL_RE = /^export\s+(?:async\s+)?(function\*?|const|let|class)\s+([A-Za-z_$][\w$]*)/gm;

const ident = (file) => '__m_' + relative(ROOT, file).replace(/[^A-Za-z0-9]/g, '_');

function parseModule(file, substitute = {}) {
  let src = substitute[file] ?? readFileSync(file, 'utf8');
  const imports = [];
  src = src.replace(IMPORT_RE, (_, names, spec) => {
    const dep = resolve(dirname(file), spec);
    const bindings = names.split(',').map((n) => n.trim()).filter(Boolean).map((n) => {
      const m = /^([A-Za-z_$][\w$]*)(?:\s+as\s+([A-Za-z_$][\w$]*))?$/.exec(n);
      if (!m) throw new Error(`${file}: unsupported import binding "${n}"`);
      return m[2] ? `${m[1]}: ${m[2]}` : m[1];
    });
    imports.push(dep);
    return `const { ${bindings.join(', ')} } = ${ident(dep)};`;
  });
  const exportsList = [];
  src = src.replace(EXPORT_DECL_RE, (match, kind, name) => {
    exportsList.push(name);
    return match.replace(/^export\s+/, '');
  });
  if (/^\s*(import|export)\b/m.test(src)) {
    throw new Error(`${file}: unsupported import/export form`);
  }
  return { file, src, imports, exportsList };
}

/**
 * Bundle `entry` (absolute path) and its relative imports into one IIFE.
 * opts.globalName: also assign the entry's exports to globalThis[globalName]
 * (used only for test helpers; extension bundles expose nothing).
 * opts.substitute: { absolutePath: source } replaces a module's text (tests
 * swap in their own data modules).
 */
export function bundle(entry, opts = {}) {
  const order = [], seen = new Set(), visiting = new Set();
  const visit = (file) => {
    if (seen.has(file)) return;
    if (visiting.has(file)) throw new Error(`import cycle at ${file}`);
    visiting.add(file);
    const mod = parseModule(file, opts.substitute);
    mod.imports.forEach(visit);
    visiting.delete(file);
    seen.add(file);
    order.push(mod);
  };
  visit(entry);
  const parts = order.map((m) =>
    `// ---- ${relative(ROOT, m.file)}\n` +
    `const ${ident(m.file)} = (() => {\n${m.src.trimEnd()}\n` +
    `return { ${m.exportsList.join(', ')} };\n})();`,
  );
  const expose = opts.globalName ? `\nglobalThis[${JSON.stringify(opts.globalName)}] = ${ident(entry)};` : '';
  return (
    `// Generated by engine/scripts/bundle.js from ${relative(ROOT, entry)}. Do not edit.\n` +
    `(() => {\n'use strict';\n${parts.join('\n\n')}${expose}\n})();\n`
  );
}

export function buildAll() {
  return TARGETS.map(({ entry, out }) => {
    const text = bundle(resolve(ROOT, entry));
    const outPath = resolve(ROOT, out);
    mkdirSync(dirname(outPath), { recursive: true });
    writeFileSync(outPath, text);
    return { out, bytes: text.length };
  });
}

if (process.argv[1] && basename(process.argv[1]) === 'bundle.js') {
  for (const { out, bytes } of buildAll()) console.log(`bundle: ${out} (${bytes} bytes)`);
}
